function validateFileTypeOptional(strSomExpFileUpload) {
  debugger;
  var objFileUpload = guideBridge.resolveNode(strSomExpFileUpload);
  var allowType = [];
  for (var i = 0; i < objFileUpload.parent.jsonModel.mimeType.length; i++) {
    allowType.push(objFileUpload.parent.jsonModel.mimeType[i].substring(objFileUpload.parent.jsonModel.mimeType[i].indexOf('/') + 1));
  }
  globalObjects.allowedTypes = allowType.join("/");
  globalObjects.fileSize = objFileUpload.parent.fileSizeLimit
  var fileName = objFileUpload.value;
  var testResult = true;
  var componentName = encrypt(objFileUpload.parent.name);
  //updated to check with capital file extensions as well
  if (objFileUpload.value) {
    var found = allowType.find(element => element == fileName.substring(fileName.lastIndexOf(".") + 1).toLowerCase());
    if (found == null || found === undefined) {
      objFileUpload.validateExpMessage = "Please upload " + allowType.join(", ") + " file";
      testResult = false;
    } else {
      $($("." + decrypt(decodeURIComponent(componentName))).find('.guideFieldWidget.afFileUpload.fileUpload')).children().prop('disabled', false);
      $($($("." + decrypt(decodeURIComponent(componentName))).find('.guideFieldWidget.afFileUpload.fileUpload')).children()[1]).attr('disabled', true);
    }
  }
  if (testResult === true && objFileUpload.value) {
    var temp = objFileUpload.value.split(".");
    var extension = temp[temp.length - 1];
  }
  return testResult;
}
function validateFileSizeOptional(componentSomExpression) {
  debugger;
  var objFileUpload = guideBridge.resolveNode(componentSomExpression);
  var componentName = encrypt(objFileUpload.parent.name);
  var isValidated = false;
  var fileSizeLimitInKB = objFileUpload.parent.fileSizeLimitInKB;
  var len = objFileUpload.parent.fileList === undefined ? 0 : objFileUpload.parent.fileList.length;
  var totalSize = 0;
  if (len === 0) {
    isValidated = true;
  }
  else {
    for (var i = 0; i < len; i++) {
      totalSize = objFileUpload.parent.fileList[i][0].files[0].size;
    }
    var fileSizeOptional;
    if (objFileUpload.parent.jsonModel.fileSizeLimit == null || objFileUpload.parent.jsonModel.fileSizeLimit == 'undefined' || objFileUpload.parent.jsonModel.fileSizeLimit == '') {
      fileSizeOptional = 2;
    }
    else {
      fileSizeOptional = parseInt(objFileUpload.parent.jsonModel.fileSizeLimit);
    }
    if ((totalSize / 1024) / 1024 <= fileSizeOptional) {
      isValidated = true;
    }
    if (isValidated === false) {
      objFileUpload.validateExpMessage = "File size should be less than " + fileSizeOptional + " MB";
    } else {
      $($("." + decrypt(decodeURIComponent(componentName))).find('.guideFieldWidget.afFileUpload.fileUpload')).children().prop('disabled', false);
      $($($("." + decrypt(decodeURIComponent(componentName))).find('.guideFieldWidget.afFileUpload.fileUpload')).children()[1]).attr('disabled', true);
    }
  }
  return isValidated;
}
