function checkTotalAttachmentSize() {
  debugger;
  var fetchfilemetadata = fetchfilemetadata2();
  var isValidated = false;
  var totalSize = 0;
  if (fetchfilemetadata.length > 0) {
    for (var i = 0; i < fetchfilemetadata.length; i++) {
      totalSize += parseInt(fetchfilemetadata[i].activityFileSize);
    }
  }
  if ((totalSize / 1024) / 1024 <= 10) {
    isValidated = true;
  }
  return isValidated;
}
function updateFileAttachmentIcon(fileObj) {
  debugger;
  var filesListObj = $("." + fileObj.name).find(".guide-fu-fileItemList");
  for (var j = 0; j < filesListObj.children().length; j++) {
    var currentFileObj = $(filesListObj).find(".guide-fu-fileItem")[j];
    var currentFileName = $(currentFileObj).find('.guide-fu-fileName');
    var iconObj = $(currentFileObj).find('.guide-fu-filePreview');
    var extenstionVal = $(currentFileName).attr('aria-label').split(".")[1];
    if (extenstionVal.toLowerCase() === "pdf") {
      $(iconObj).addClass("pdfIconInsideAttach");
    } else {
      $(iconObj).addClass("imageIconInsideAttach");
    }
  }
}
